if (a >= b) {
    throw std::invalid_argument("Left bound must be less than right bound");
}

double fa = f(a);
double fb = f(b);

if (fa * fb > 0) {
    throw std::invalid_argument("Function must have opposite signs at endpoints");
}

if (std::abs(fa) < precision) {
    return a;
}

if (std::abs(fb) < precision) {
    return b;
}

for (unsigned int i = 0; i < max_iter; i++) {
    double c = (a + b) / 2.0;
    double fc = f(c);

    if (std::abs(fc) < precision || (b - a) / 2.0 < precision) {
        return c;
    }

    if (fa * fc < 0) {
        b = c;
        fb = fc;
    } else {
        a = c;
        fa = fc;
    }
}

throw std::runtime_error("Maximum iterations reached without convergence");
// END_CODE

